class Solution {
    public String reverseParentheses(String s) {
        int n = s.length();
        int[] pairIdx = new int[n];
        int[] st = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == '(') st[top++] = i;
            else if (ch == ')') {
                int j = st[--top];
                pairIdx[i] = j;
                pairIdx[j] = i;
            }
        }
        StringBuilder sb = new StringBuilder();
        int curr = 0, step = 1;
        while (curr < n) {
            char ch = s.charAt(curr);
            if (ch == '(' || ch == ')') {
                curr = pairIdx[curr];
                step = -step;
            } else {
                sb.append(ch);
            }
            curr += step;
        }
        return sb.toString();
    }
}

var reverseParentheses = function(s) {
    const n = s.length;
    const pairIdx = new Array(n).fill(0);
    const st = [];
    for (let i = 0; i < n; i++) {
        if (s[i] === '(') st.push(i);
        else if (s[i] === ')') {
            const j = st.pop();
            pairIdx[i] = j;
            pairIdx[j] = i;
        }
    }
    const res = [];
    let curr = 0, step = 1;
    while (curr < n) {
        if (s[curr] === '(' || s[curr] === ')') {
            curr = pairIdx[curr];
            step = -step;
        } else {
            res.push(s[curr]);
        }
        curr += step;
    }
    return res.join('');
};
